from http.server import HTTPServer, BaseHTTPRequestHandler
import base64
import sys
import os

# Check if preload.so exists
if not os.path.exists('preload.so'):
    print("Error: preload.so not found!")
    sys.exit(1)

# Our preload.so content in base64
try:
    PRELOAD_SO = base64.b64encode(open('preload.so', 'rb').read())
except Exception as e:
    print(f"Error reading preload.so: {e}")
    sys.exit(1)

class Handler(BaseHTTPRequestHandler):
    def do_GET(self):
        self.send_response(200)
        self.send_header('Content-Type', 'application/octet-stream')
        self.end_headers()
        self.wfile.write(PRELOAD_SO)

    def log_message(self, format, *args):
        # Override to disable logging
        pass

def main():
    port = 9999
    try:
        httpd = HTTPServer(('0.0.0.0', port), Handler)
        print(f'Serving preload.so on port {port}...')
        httpd.serve_forever()
    except Exception as e:
        print(f"Error starting server: {e}")
        sys.exit(1)

if __name__ == '__main__':
    main()

#!/usr/bin/env python3
from http.server import HTTPServer, BaseHTTPRequestHandler
import base64
import socket
import sys

# Our preload.so content in base64
try:
    PRELOAD_SO = base64.b64encode(open('preload.so', 'rb').read())
except Exception as e:
    print(f"Error reading preload.so: {e}")
    sys.exit(1)

class Handler(BaseHTTPRequestHandler):
    def do_GET(self):
        self.send_response(200)
        self.send_header('Content-Type', 'application/octet-stream')
        self.end_headers()
        self.wfile.write(PRELOAD_SO)

def main():
    port = 9999
    try:
        httpd = HTTPServer(('0.0.0.0', port), Handler)
        print(f'Serving preload.so on port {port}...')
        httpd.serve_forever()
    except socket.error as e:
        print(f"Failed to start server: {e}")
        sys.exit(1)
    except KeyboardInterrupt:
        print("\nShutting down server...")
        httpd.socket.close()
        sys.exit(0)

if __name__ == '__main__':
    main()

